package io.colorsand.ui

import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.darkColorScheme
import androidx.compose.runtime.Composable
import androidx.compose.runtime.CompositionLocalProvider
import androidx.compose.runtime.staticCompositionLocalOf
import androidx.compose.ui.graphics.Color
import io.colorsand.core.SandColor

/** A color scheme: the sand colors plus the colors of the screen around them. */
class Palette(
    val name: String,
    /** Display color of each sand color. */
    val sand: (SandColor) -> Color,
    val backgroundTop: Color,
    val backgroundBottom: Color,
    /** Titles and the main button. */
    val accent: Color,
    /** Text on [accent]. */
    val onAccent: Color,
    /** Hints and notices. */
    val highlight: Color,
    /** A finished tube's outline. */
    val done: Color,
    val surface: Color,
    val text: Color,
    val dimText: Color,
)

object Palettes {
    val Classic = Palette(
        name = "Classic",
        sand = { Color(0xFF000000 or it.rgb.toLong()) },
        backgroundTop = Color(0xFF1B1F3B),
        backgroundBottom = Color(0xFF3B2F5C),
        accent = Color(0xFFF4E4C1),
        onAccent = Color(0xFF1B1F3B),
        highlight = Color(0xFFFFD54F),
        done = Color(0xFF9CCC65),
        surface = Color(0xFF2A2F55),
        text = Color.White,
        dimText = Color.White.copy(alpha = 0.7f),
    )

    val all: List<Palette> = listOf(Classic)
}

/** The palette in use. Read it wherever something is drawn in color. */
val LocalPalette = staticCompositionLocalOf { Palettes.Classic }

@Composable
fun ColorSandTheme(palette: Palette, content: @Composable () -> Unit) {
    val colors = darkColorScheme(
        primary = palette.accent,
        onPrimary = palette.onAccent,
        secondary = palette.highlight,
        background = palette.backgroundTop,
        surface = palette.surface,
        onSurface = palette.text,
    )
    CompositionLocalProvider(LocalPalette provides palette) {
        MaterialTheme(colorScheme = colors, content = content)
    }
}
